<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';
use Omnigo\{Database,InventorySchema,InventoryCatalog,InventoryStock,InventoryProjection,InventoryRead,InventoryTotals,InventoryTotalMonitor,InventoryProgress,InventorySettings};
$db=new Database(['dsn'=>'sqlite::memory:']);
$db->run('CREATE TABLE companies(id INTEGER PRIMARY KEY)');
$db->run('CREATE TABLE company_profiles(company_id INTEGER PRIMARY KEY,payload TEXT,version INTEGER DEFAULT 1)');
$db->run('CREATE TABLE records(company_id INTEGER,kind TEXT,payload TEXT,updated TEXT)');
foreach([1,2] as $id){$db->run('INSERT INTO companies(id) VALUES(?)',[$id]);$db->run('INSERT INTO company_profiles(company_id,payload) VALUES(?,?)',[$id,json_encode(['workspacePolicy'=>['inventory'=>['mode'=>'both']]])]);}
InventorySchema::install($db);$checks=0;
function verify(bool $ok,string $message):void{global $checks;if(!$ok)throw new RuntimeException($message);$checks++;}
function rejects(callable $fn,string $message):void{try{$fn();}catch(InvalidArgumentException|DomainException|OutOfBoundsException){verify(true,$message);return;}verify(false,$message);}
$catalog=new InventoryCatalog($db);$stock=new InventoryStock($db);$projection=new InventoryProjection($db);
$listing=['id'=>'HB-1','title'=>'Profilo BD3056WDNN','sku'=>'MODEL-1','barcode'=>'4242006322427','quantity'=>25,'saleActive'=>true];
$key=$catalog->ingest(1,'Hepsiburada',$listing);
verify($catalog->ingest(1,'n11',[...$listing,'id'=>'n11-1','sku'=>'other-sku','title'=>'Başka ürün'])!==$key,'Aynı barkod farklı SKU’ları birleştirmez.');
$catalog->ingest(2,'Hepsiburada',$listing);
verify($catalog->matchSku(1,'Hepsiburada','MODEL-1')===$key,'SKU kendi kaynağıyla eşleşir.');
verify($catalog->matchSku(1,'idefix','MODEL-1')===null,'Kaynaklar arasında yanlış SKU eşleşmez.');
verify(!InventoryCatalog::validGtin('BD3056WDNN')&&!InventoryCatalog::validGtin('4242006322428'),'Model kodu ve hatalı barkod reddedilir.');
$first=$stock->change(1,$key,'request-first-count',1,'set',25,1,'İlk sayım');
$quantity=fn()=>(int)$db->one('SELECT quantity FROM inventory_products WHERE company_id=1 AND product_key=?',[$key])['quantity'];
$line=['provider'=>'Hepsiburada','lineKey'=>hash('sha256','O1:L1'),'productKey'=>$key,'orderNumber'=>'O1','placedAt'=>gmdate('c'),'ordered'=>7,'cancelled'=>0,'returned'=>0,'invoiceCents'=>700000];
$projection->apply(1,$line,1);verify($quantity()===25,'Online satış mağaza havuzunu azaltmaz.');
verify(!$projection->apply(1,$line,1),'Aynı kaynak sürümü tekrarlanmaz.');
$projection->apply(1,[...$line,'cancelled'=>2,'returned'=>1],2);verify($quantity()===25,'İptal/iade mağaza havuzunu değiştirmez.');
verify(!$projection->apply(1,$line,1),'Gecikmiş eski durum yeni durumu ezmez.');
rejects(fn()=>$projection->apply(1,$line,2),'Aynı sürümde çelişen durum reddedilir.');
$projection->apply(1,[...$line,'lineKey'=>hash('sha256','OLD'),'orderNumber'=>'OLD','placedAt'=>'2020-01-01T00:00:00Z'],3);verify($quantity()===25,'Geçmiş sipariş stoğu düşürmez.');
verify($stock->change(1,$key,'request-first-count',1,'set',25,1,'İlk sayım')['replayed'],'Manuel isteğin tekrarı ikinci kez uygulanmaz.');
rejects(fn()=>$stock->change(1,$key,'request-stale-count',1,'set',100,1,'Eski sayım'),'Eski ekrandan kayıt engellenir.');
$version=fn()=>(int)$db->one('SELECT version FROM inventory_products WHERE company_id=1 AND product_key=?',[$key])['version'];
$stock->change(1,$key,'request-store-sale',$version(),'store_sale',30,1,'Mağaza satışı');verify($quantity()===-5,'Mağaza stok eksiye düşebilir.');
$stock->change(1,$key,'request-new-receipt',$version(),'add',10,1,'Ürün girişi');verify($quantity()===5,'Ürün girişi negatif stoğa eklenir.');
verify($db->one('SELECT quantity FROM inventory_products WHERE company_id=2 AND product_key=?',[$key])['quantity']===null,'Diğer müşteri değişmez.');
$db->run('UPDATE company_profiles SET payload=? WHERE company_id=2',[json_encode(['workspacePolicy'=>['inventory'=>['mode'=>'marketplace']]])]);
rejects(fn()=>$stock->change(2,$key,'request-forbidden-set',1,'set',12,1,'Sayım'),'Yalnız pazaryeri modu elle stok kabul etmez.');
$sources=[['quantity'=>25,'health'=>'current'],['quantity'=>25,'health'=>'current']];
verify(InventoryTotals::calculate('both',25,$sources)['totalQuantity']===50,'Ortak online stok kaynak sayısıyla çarpılmaz.');
verify(InventoryTotals::calculate('both',21,$sources)['totalQuantity']===46,'Mağaza satışı yalnız mağaza havuzundan düşer.');
verify(InventoryTotals::calculate('both',25,[['quantity'=>24,'health'=>'current']])['totalQuantity']===49,'Kaynak online satışı toplamda bir kere etkiler.');
$different=InventoryTotals::calculate('both',25,[...$sources,['quantity'=>24,'health'=>'current']]);
verify($different['marketplaceStockDifferent']&&$different['totalQuantity']===$different['marketplaceQuantity']+25,'Farklı stoklar toplanmaz; seçilen kaynağa mağaza stoğu eklenir.');
verify($different['verifiedTotalQuantity']===null&&!$different['critical'],'Farklı kaynaklar yanlış stok bitti bildirimi üretmez.');
verify(InventoryTotals::calculate('both',25,[['quantity'=>25,'health'=>'stale']])['totalQuantity']===null,'Eski kaynak kesin stok sayılmaz.');
$monitor=new InventoryTotalMonitor($db);$monitor->observe(1,$key,3);$monitor->observe(1,$key,1);
verify((int)$db->one('SELECT COUNT(*) n FROM inventory_alerts')['n']===0,'Üç adet kritik uyarı üretmez.');
$monitor->observe(1,$key,0);$monitor->observe(1,$key,-1);$monitor->observe(1,$key,-1);
verify((int)$db->one('SELECT COUNT(*) n FROM inventory_alerts')['n']===1,'Sıfıra geçişte tek bildirim.');
$monitor->observe(1,$key,10);$monitor->observe(1,$key,0);
verify((int)$db->one('SELECT COUNT(*) n FROM inventory_alerts WHERE quantity<=0')['n']===2,'Yeniden dolup bitince ikinci tükenme bildirimi.');
verify((int)$db->one('SELECT COUNT(*) n FROM inventory_alerts WHERE quantity>0')['n']===1,'Aradaki yeniden stok gelişi ayrıca izlenir.');
$progress=new InventoryProgress($db);$progress->ensure(1,'hepsiburada');$job=$progress->claim(1,'hepsiburada');
verify($job!==null&&$progress->claim(1,'hepsiburada')===null,'İki cihaz aynı aktarımı eşzamanlı çalıştıramaz.');
$progress->commit(1,$job,['items'=>[$listing],'next'=>true,'totalPages'=>2]);
verify((int)$db->one('SELECT page_no FROM inventory_catalog_jobs WHERE company_id=1')['page_no']===1,'Sayfa ve ürünler birlikte kaydedilir.');
$db->run('UPDATE inventory_catalog_jobs SET next_run=0 WHERE company_id=1');$job=$progress->claim(1,'hepsiburada');$progress->fail(1,$job,new RuntimeException('gizli erişim bilgisi'));
verify($progress->status(1)['state']==='retry'&&$progress->status(1)['percent']!==100,'Hata tamamlandı sayılmaz.');
verify(!str_contains($progress->status(1)['providers'][0]['error'],'gizli'),'Hata erişim bilgisi sızdırmaz.');
$db->run('UPDATE inventory_catalog_jobs SET next_run=0 WHERE company_id=1');$job=$progress->claim(1,'hepsiburada');
verify((int)$job['page_no']===1,'Kesinti sonrası kaldığı sayfadan devam eder.');
$progress->commit(1,$job,['items'=>[[...$listing,'id'=>'HB-2','sku'=>'MODEL-2','title'=>'İkinci ürün']],'next'=>false,'totalPages'=>2]);
verify($progress->status(1)['percent']===100,'Tüm sayfalar ve stoklar tamamlandığında yüzde yüz.');
$result=(new InventoryRead($db))->listing(1,'BD3056',0,'all');verify($result['total']===1,'Tüm ürünler listesinde tekilleştirilmiş liste doğru.');
verify((new InventoryRead($db))->listing(1,'%',0,'all')['total']===0,'Arama SQL jokerlerini kaçırır.');
echo "$checks stok, kuyruk ve müşteri yalıtımı kontrolü geçti.\n";
